using System;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RandomEnemyLightningAction", menuName = "Data/Battle/Battle Actions/Purification Actions/RandomEnemyLightning Action")]
public class RandomEnemyLightningAction : RandomLightningAction
{
	public override void CastAmount(int actionAmount, GameObject source)
	{
		CastVariableTimes(actionAmount, currentCorruptedAnimals.activeCorruptedAnimals.Duplicate(), source);
	}

	public void CastSothisSandstorm(int timesAmount, int purifyAmount, GameObject source, float delayToStartCorruptedLightningAction, Action beforeDelayAction, Action afterLightningAction)
	{
		CastVariableAndTimesAmountWithActionAndDelayToStart(timesAmount, purifyAmount, currentCorruptedAnimals.activeCorruptedAnimals.Duplicate(), source, delayToStartCorruptedLightningAction, afterLightningAction, null, beforeDelayAction);
	}

	public void CastVariableAndTimesAmount(int timesAmount, int purifyAmount, GameObject source)
	{
		CastVariableAndTimesAmount(timesAmount, purifyAmount, currentCorruptedAnimals.activeCorruptedAnimals.Duplicate(), source);
	}
}
